import math

def is_perfect_cube(n):
    if n == 0:
        return True
    # Handle negative numbers by taking absolute value for root finding
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Calculate the integer cube root
    # We use round(n**(1/3)) for estimation, then check nearby integers
    root = round(n**(1/3))

    # Check the root and its neighbors
    for k in range(max(1, root - 2), root + 3):
        if k**3 == n:
            return True

    return False

def calculate_expression(x):
    return (8*x - 41) * (x + 3)**2

results = {}
for x in range(-5, 6):
    value = calculate_expression(x)
    is_cube = is_perfect_cube(value)
    results[x] = (value, is_cube)

print(results)

